package io.github.diodeme.ji.acp.v1;

import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;

/** Fails before a single in-flight NDJSON record can exceed the configured byte budget. */
final class BoundedInputStream extends FilterInputStream {
    private final int maximumLineBytes;
    private int lineBytes;

    BoundedInputStream(InputStream input, int maximumLineBytes) {
        super(input);
        if (maximumLineBytes < 1) throw new IllegalArgumentException("maximumLineBytes must be positive");
        this.maximumLineBytes = maximumLineBytes;
    }

    @Override
    public int read() throws IOException {
        int value = super.read();
        if (value >= 0) account(value);
        return value;
    }

    @Override
    public int read(byte[] bytes, int offset, int length) throws IOException {
        int count = super.read(bytes, offset, length);
        for (int index = 0; index < count; index++) account(bytes[offset + index] & 0xff);
        return count;
    }

    private void account(int value) throws IOException {
        if (value == '\n') {
            lineBytes = 0;
            return;
        }
        lineBytes = Math.incrementExact(lineBytes);
        if (lineBytes > maximumLineBytes) throw new IOException("ACP input message exceeds byte limit");
    }
}
